export interface Note {
  id: number;
  title: string;
  content: string;
  category: string;
}

export const NOTE_CATEGORIES = ["Kuliah", "Tugas", "Pribadi", "Organisasi"];

import { useState, useEffect } from "react";

export function useLocalStorage<T>(key: string, initialValue: T) {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = localStorage.getItem(key);
      return item ? (JSON.parse(item) as T) : initialValue;
    } catch {
      return initialValue;
    }
  });

  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(storedValue));
  }, [key, storedValue]);

  return [storedValue, setStoredValue] as const;
}

import { useState } from "react";
import { NOTE_CATEGORIES, type Note } from "../types/Note";

interface NoteFormProps {
  onAddNote: (newNote: Omit<Note, "id">) => void;
}

export default function NoteForm({ onAddNote }: NoteFormProps) {
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [category, setCategory] = useState(NOTE_CATEGORIES[0]);

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!title.trim()) return;

    onAddNote({
      title: title.trim(),
      content: content.trim(),
      category,
    });

    setTitle("");
    setContent("");
    setCategory(NOTE_CATEGORIES[0]);
  };

  return (
    <form className="note-form" onSubmit={handleSubmit}>
      <div className="form-row">
        <div className="form-field">
          <label htmlFor="title">Judul Catatan</label>
          <input
            id="title"
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Masukkan judul catatan..."
            required
          />
        </div>
        <div className="form-field category-field">
          <label htmlFor="category">Kategori</label>
          <select
            id="category"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
          >
            {NOTE_CATEGORIES.map((cat) => (
              <option key={cat} value={cat}>
                {cat}
              </option>
            ))}
          </select>
        </div>
      </div>

      <div className="form-field">
        <label htmlFor="content">Isi Catatan</label>
        <textarea
          id="content"
          rows={3}
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Tulis detail catatan di sini..."
        />
      </div>

      <button type="submit" className="btn-add">
        Tambah Catatan
      </button>
    </form>
  );
}

import type { Note } from "../types/Note";

